import{_ as c,E as a,h as o,c as u,b as t,f as r,H as n,w as i,l as p,a3 as h,a4 as m}from"./chunks/framework.B_fYP6Of.js";const y=JSON.parse('{"title":"System architecture","description":"Follow one question and one document revision through the proposed RAG architecture, from browser request to evidence retrieval and index publication.","frontmatter":{"title":"System architecture","description":"Follow one question and one document revision through the proposed RAG architecture, from browser request to evidence retrieval and index publication.","teaser":"One reader wants an answer now. Someone else has just uploaded a corrected report. Follow those two requests to see why chat and ingestion need different owners."},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md"}'),b={name:"architecture/overview.md"};function v(g,e,w,f,A,S){const s=a("LabArticleHeader"),d=a("Mermaid"),l=a("LabScroll");return o(),u("div",null,[e[1]||(e[1]=t("h1",{id:"system-architecture",tabindex:"-1"},[r("System architecture "),t("a",{class:"header-anchor",href:"#system-architecture","aria-label":'Permalink to "System architecture"'},"​")],-1)),n(s),e[2]||(e[2]=t("p",null,[t("span",{class:"status-label"},"DRAFT · DESIGN BASELINE")],-1)),e[3]||(e[3]=t("p",null,"There are two clocks in this design. A reader is waiting for a cited answer. In the background, a new document may take minutes to parse, link, and index. The system should answer using an eligible, published revision and switch to newer evidence only when the declared retrieval capabilities are ready.",-1)),e[4]||(e[4]=t("p",null,"Trace the live conversation first, then follow a source through ingestion. The design makes both paths measurable. Model time, retrieval, queueing, network travel, and browser rendering all contribute to what the reader experiences.",-1)),e[5]||(e[5]=t("h2",{id:"system-boundaries",tabindex:"-1"},[r("System boundaries "),t("a",{class:"header-anchor",href:"#system-boundaries","aria-label":'Permalink to "System boundaries"'},"​")],-1)),n(l,{kind:"diagram",label:"diagram for System boundaries"},{default:i(()=>[(o(),p(h,null,{default:i(()=>[n(d,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20TB%0A%20%20accTitle%3A%20Chat%20and%20publication%20paths%0A%20%20accDescr%3A%20The%20browser%20exchanges%20commands%20and%20streamed%20answers%20with%20Rust.%20Rust%20retrieves%20published%20evidence%20and%20calls%20the%20model.%20In%20a%20separate%20path%2C%20source%20revisions%20go%20through%20parsing%20and%20publication%2C%20which%20updates%20the%20index%20and%20emits%20an%20event.%0A%20%20UI%5B%22SvelteKit%20browser%20interface%22%5D%20%3C--%3E%7C%22HTTP%20commands%20%2F%20SSE%22%7C%20CHAT%5B%22Rust%20chat%20service%22%5D%0A%20%20SSR%5B%22SvelteKit%20initial%20rendering%22%5D%20--%3E%20UI%0A%20%20CHAT%20--%3E%20RET%5B%22Retrieval%20application%20boundary%22%5D%0A%20%20RET%20--%3E%20DB%5B%22SQLite%20candidate%3A%20FTS5%20%2F%20vectors%20%2F%20graph%22%5D%0A%20%20CHAT%20%3C--%3E%7C%22Generation%20%2F%20cancellation%20where%20supported%22%7C%20MODEL%5B%22Model%20endpoint%22%5D%0A%20%20ORCH%5B%22One%20durable%20DAG%20orchestrator%22%5D%20--%3E%20NLP%5B%22Parsing%20and%20NLP%20workers%22%5D%0A%20%20NLP%20--%3E%20WRITER%5B%22Index%20publication%20owner%22%5D%0A%20%20WRITER%20--%3E%20DB%0A%20%20WRITER%20--%3E%20EVENTS%5B%22NATS%20%2F%20JetStream%20domain%20events%22%5D%0A%20%20EVENTS%20--%3E%20CHAT%0A%20%20SOURCE%5B%22Document%20revisions%22%5D%20--%3E%20ORCH%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1}))]),_:1}),e[6]||(e[6]=m('<p>Use the boxes to find the owner of a failure. If the browser receives a stale completion, start with run ownership. If search returns a superseded source, start with publication and retrieval. Several boxes can share one process. Add a process boundary only after checking resource isolation, failure ownership, database locality, and model placement.</p><h2 id="conversation-path" tabindex="-1">Conversation path <a class="header-anchor" href="#conversation-path" aria-label="Permalink to &quot;Conversation path&quot;">​</a></h2><p>The browser submits an idempotent message command. Rust authorizes access, creates a run, retrieves eligible evidence, builds bounded context, and streams model output as structured events. One authoritative run owner decides ordering, cancellation, completion, and failure. UI event order is scoped by run and attempt.</p><p>SvelteKit may render the initial page and a bounded history snapshot. Active tokens travel directly from Rust to the browser. No frontend server proxy is required in that path. The snapshot includes a checkpoint per resumable run so the client can catch up without a replay/live subscription gap; cursors are scoped to that run and attempt.</p><p>Direct SSE is the default. A retained run-output log and separate generation workers are justified if independent generation, multiple viewers, or cross-device catch-up become required. Replaying recorded text does not resume a failed inference process.</p><h2 id="knowledge-path" tabindex="-1">Knowledge path <a class="header-anchor" href="#knowledge-path" aria-label="Permalink to &quot;Knowledge path&quot;">​</a></h2><p>BM25 and vector retrieval produce candidates over eligible document revisions. Combine ranks, expand selected graph relationships within explicit bounds, optionally rerank, and fetch original evidence. Every result carries document version and source anchors. Entity linking and graph traversal complement lexical and semantic search.</p><p>SQLite is a candidate for local retrieval, not an approved distributed database. <a href="/knowledge-lab/architecture/retrieval">Retrieval storage</a> describes extension capabilities, single-writer constraints, filtering correctness, and replacement seams.</p><h2 id="ingestion-path" tabindex="-1">Ingestion path <a class="header-anchor" href="#ingestion-path" aria-label="Permalink to &quot;Ingestion path&quot;">​</a></h2><p>A source revision creates a durable workflow. Parsing preserves structure and source locations. Retrieval chunks and larger extraction windows support different tasks. Embeddings and lexical indexing can progress independently of entity resolution, claim validation, and augmentation.</p><p>The orchestrator owns dependencies, retries, and readiness. NATS carries appropriate boundary events; it does not become a second scheduler. If the chosen orchestrator provides task queues, use its own execution protocol for those activities.</p><h2 id="principles-carried-into-this-draft" tabindex="-1">Principles carried into this draft <a class="header-anchor" href="#principles-carried-into-this-draft" aria-label="Permalink to &quot;Principles carried into this draft&quot;">​</a></h2><ol><li>Core evidence and run policies do not import Axum, SQLite, NATS, or an orchestration SDK.</li><li>Adapter contracts expose filtering, approximate-search, cancellation, and snapshot limitations.</li><li>One owner governs each state machine and one publication rule selects current artifacts.</li><li>Buffers, retrieval fanout, graph expansion, background compute, and retry budgets are bounded.</li><li>Source claims, resolution decisions, and generated augmentations remain distinguishable.</li></ol><p>These constraints respond to the <a href="/knowledge-lab/reviews/">three design reviews</a>. They are requirements for implementation and future tests, rather than evidence that an implementation already satisfies them.</p>',14))])}const x=c(b,[["render",v]]);export{y as __pageData,x as default};
